export type CollapsePlan = {
  before: number;
  afterStart: number;
};

export function getCollapsePlan(
  total: number,
  maxItems: number,
  itemsBeforeCollapse: number,
  itemsAfterCollapse: number | undefined,
): CollapsePlan | null {
  if (total <= maxItems) return null;

  const before = itemsBeforeCollapse;
  const after = itemsAfterCollapse ?? maxItems - before;

  if (after <= 0 || before + after >= total) return null;

  return {
    before,
    afterStart: total - after,
  };
}

/* Alert component tokens. */
:root {
  --alert-radius: var(--radius-6);
}

/* Avatar component tokens — override these to customise avatars. */
:root {
  /* Per-size dimensions */
  --avatar-xs-size: 16px;
  --avatar-sm-size: 20px;
  --avatar-md-size: 24px;
  --avatar-lg-size: 28px;
  --avatar-xl-size: 32px;
  --avatar-2xl-size: 40px;
  --avatar-3xl-size: 46px;

  /* Per-size square radii (frappe-ui v1) */
  --avatar-xs-radius: 4px;
  --avatar-sm-radius: 5px;
  --avatar-md-radius: 5px;
  --avatar-lg-radius: 6px;
  --avatar-xl-radius: 6px;
  --avatar-2xl-radius: 8px;
  --avatar-3xl-radius: 10px;

  /* Per-size initials font sizes */
  --avatar-xs-font-size: 11px;
  --avatar-sm-font-size: 13px;
  --avatar-md-font-size: 14px;
  --avatar-lg-font-size: 14px;
  --avatar-xl-font-size: 16px;
  --avatar-2xl-font-size: 18px;
  --avatar-3xl-font-size: 20px;

  /* Per-size fallback icon sizes */
  --avatar-xs-icon-size: 10px;
  --avatar-sm-icon-size: 12px;
  --avatar-md-icon-size: 14px;
  --avatar-lg-icon-size: 16px;
  --avatar-xl-icon-size: 18px;
  --avatar-2xl-icon-size: 22px;
  --avatar-3xl-icon-size: 24px;

  /* Surfaces */
  --avatar-bg: var(--surface-gray-2);
  --avatar-fg: var(--ink-gray-5);

  /* Indicator shell — slot content fills the shell */
  --avatar-status-icon-size: 6px;
  --avatar-status-bg: var(--surface-base);
  --avatar-status-ring: var(--surface-base);
  --avatar-status-ring-width: 2px;
}

/* Avatar group component tokens — override these to customise avatar stacks. */
:root {
  --avatar-group-ring: var(--surface-base);
  --avatar-group-ring-width: 2px;

  --avatar-group-overlap-xs: 2px;
  --avatar-group-overlap-sm: 4px;
  --avatar-group-overlap-md: 4px;
  --avatar-group-overlap-lg: 5px;
  --avatar-group-overlap-xl: 4px;
  --avatar-group-overlap-2xl: 6px;
  --avatar-group-overlap-3xl: 8px;

  --avatar-group-label-fg: var(--ink-gray-5);

  --avatar-group-label-xs-font-size: 11px;
  --avatar-group-label-sm-font-size: 11px;
  --avatar-group-label-md-font-size: 14px;
  --avatar-group-label-lg-font-size: 14px;
  --avatar-group-label-xl-font-size: 16px;
  --avatar-group-label-2xl-font-size: 18px;
  --avatar-group-label-3xl-font-size: 20px;
}

/* Badge component tokens — override these to customise badges. */
:root {
  --badge-gap: 4px;
  --badge-radius: var(--radius-full);

  /* Size: sm */
  --badge-sm-height: 16px;
  --badge-sm-px: 6px;
  --badge-sm-font-size: 12px;
  --badge-sm-icon-size: 10px;

  /* Size: md */
  --badge-md-height: 20px;
  --badge-md-px: 6px;
  --badge-md-font-size: 12px;
  --badge-md-icon-size: 10px;

  /* Size: lg */
  --badge-lg-height: 24px;
  --badge-lg-px: 8px;
  --badge-lg-font-size: 13px;
  --badge-lg-icon-size: 12px;
}

/* Breadcrumb component tokens — override these to customise breadcrumbs. */
:root {
  --breadcrumb-list-gap: 2px;
  --breadcrumb-item-radius: var(--radius-4);
  --breadcrumb-ellipsis-radius: var(--radius-4);

  /* duration-press-hover: 120–180ms for hover and press feedback */
  --breadcrumb-transition-duration: 150ms;
  --breadcrumb-transition-easing: ease-out;

  /* ux-fitts-hit-area: invisible expansion beyond visible bounds */
  --breadcrumb-hit-inset: -6px -8px;

  --breadcrumb-link-fg: var(--ink-gray-5);
  --breadcrumb-link-hover-fg: var(--ink-gray-7);
  --breadcrumb-page-fg: var(--ink-gray-9);
  --breadcrumb-separator-fg: var(--ink-gray-4);

  /* Size: sm — ux-fitts-target-size: min 32px interactive height */
  --breadcrumb-sm-py: 3px;
  --breadcrumb-sm-px: 4px;
  --breadcrumb-sm-font-size: 14px;
  --breadcrumb-sm-icon-size: 16px;
  --breadcrumb-sm-min-height: 32px;
  --breadcrumb-sm-ellipsis-size: 32px;

  /* Size: md */
  --breadcrumb-md-py: 5px;
  --breadcrumb-md-px: 5px;
  --breadcrumb-md-font-size: 16px;
  --breadcrumb-md-icon-size: 16px;
  --breadcrumb-md-min-height: 32px;
  --breadcrumb-md-ellipsis-size: 32px;

  /* Collapsed items menu (ellipsis dropdown) */
  --breadcrumb-menu-min-width: 160px;
  --breadcrumb-menu-radius: var(--radius-6);
  --breadcrumb-menu-border: var(--outline-gray-1);
  --breadcrumb-menu-bg: var(--surface-elevation-2);
  --breadcrumb-menu-fg: var(--ink-gray-8);
  --breadcrumb-menu-shadow: var(--shadow-md);
  --breadcrumb-menu-item-radius: var(--radius-3);
  --breadcrumb-menu-item-px: 8px;
  --breadcrumb-menu-item-py: 6px;
  --breadcrumb-menu-item-font-size: 14px;
  --breadcrumb-menu-item-highlight-bg: var(--surface-gray-2);
  --breadcrumb-menu-item-highlight-fg: var(--ink-gray-8);
}

/* Button component tokens — override these to customise the button. */
:root {
  /* Size: xs */
  --btn-xs-height: 24px;
  --btn-xs-px: 6px;
  --btn-xs-radius: var(--radius-3);
  --btn-xs-font-size: 12px;

  /* Size: sm */
  --btn-sm-height: 28px;
  --btn-sm-px: 8px;
  --btn-sm-radius: var(--radius-4);
  --btn-sm-font-size: 14px;

  /* Size: md */
  --btn-md-height: 32px;
  --btn-md-px: 10px;
  --btn-md-radius: var(--radius-4);
  --btn-md-font-size: 14px;

  /* Size: lg */
  --btn-lg-height: 40px;
  --btn-lg-px: 12px;
  --btn-lg-radius: var(--radius-5);
  --btn-lg-font-size: 16px;
}

/* Checkbox component tokens — mirrors frappe-ui v1 toggle geometry. */
:root {
  --checkbox-xs-size: 13px;
  --checkbox-sm-size: 14px;
  --checkbox-md-size: 16px;
  --checkbox-radius: var(--radius-1);
  --checkbox-padded-radius: var(--radius-4);
  --checkbox-label-gap: 8px;

  --checkbox-xs-height: 24px;
  --checkbox-sm-height: 28px;
  --checkbox-md-height: 32px;

  --input-description-font-size: 13px;
}

/* The dialog enters on a short scale-and-lift, and the scrim fades. */
@keyframes espresso-dialog-overlay-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

@keyframes espresso-dialog-content-in {
  from {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* The scrim is heavier in the dark theme, so the card still reads as the
   surface in front. */
[data-theme="dark"] [data-slot="dialog-overlay"] {
  background-color: var(--color-black-overlay-700);
}

[data-slot="dialog-overlay"][data-state="open"] {
  animation: espresso-dialog-overlay-in 150ms ease-out;
}

[data-slot="dialog-overlay"][data-state="closed"] {
  animation: espresso-dialog-overlay-in 150ms ease-out reverse;
}

[data-slot="dialog-content"][data-state="open"] {
  animation: espresso-dialog-content-in 180ms cubic-bezier(0.23, 1, 0.32, 1);
}

[data-slot="dialog-content"][data-state="closed"] {
  animation: espresso-dialog-content-in 180ms cubic-bezier(0.23, 1, 0.32, 1) reverse;
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="dialog-overlay"],
  [data-slot="dialog-content"] {
    animation: none;
  }
}

/* Key chips keep their own baseline so a row of them reads as one line. */
[data-slot="keyboard-shortcut"] kbd {
  font-family: inherit;
}

/* Label component tokens — mirrors frappe-ui v1 FormLabel. */
:root {
  --label-font-size: 13px;
  --label-font-weight: 420;
  --label-color: var(--ink-gray-6);
  --label-disabled-color: var(--ink-gray-4);
  --label-required-color: var(--ink-red-5);
}

/* The spinner sits on the text baseline; the negative start margin pulls it
   into the line so the row reads as one line of text. */
[data-slot="loading-text"] {
  line-height: 1;
}

/* Progress component tokens. */
:root {
  --progress-sm-height: 2px;
  --progress-md-height: 4px;
  --progress-lg-height: 8px;
  --progress-xl-height: 12px;
  --progress-radius: var(--radius-7);
  --progress-gap: 4px;
  --progress-transition-duration: 660ms;
  --progress-ease: cubic-bezier(0.65, 0, 0.35, 1);
}

/* RadioGroup and Radio tokens — frappe-ui v1 control geometry. */
:root {
  /* Control diameter: xs 13px / sm 14px / md 16px */
  --radio-xs-size: 13px;
  --radio-sm-size: 14px;
  --radio-md-size: 16px;

  /* Selected ring width leaves a surface-base hole in the centre. */
  --radio-xs-checked-border: 3.7px;
  --radio-sm-checked-border: 4px;
  --radio-md-checked-border: 4.5px;

  /* Optical offset from the first line of the label. */
  --radio-xs-offset: 4px;
  --radio-sm-offset: 3.5px;
  --radio-md-offset: 2.5px;

  --radio-padded-radius: var(--radius-4);
}

/* Each star is drawn twice, clipped at the midline, so half stars work. */
[data-slot="star"] {
  background: transparent;
  padding: 0;
  border: 0;
}

[data-slot="half-left"] {
  clip-path: inset(0 50% 0 0);
}

[data-slot="half-right"] {
  clip-path: inset(0 0 0 50%);
}

/* TextInput component tokens — mirrors frappe-ui v1 control geometry. */
:root {
  /* Size: xs (24px) */
  --input-xs-height: 24px;
  --input-xs-radius: var(--radius-3);
  --input-xs-font-size: 12px;

  /* Size: sm (28px) */
  --input-sm-height: 28px;
  --input-sm-radius: var(--radius-4);
  --input-sm-font-size: 14px;

  /* Size: md (32px) */
  --input-md-height: 32px;
  --input-md-radius: var(--radius-4);
  --input-md-font-size: 14px;

  /* Size: lg (40px) */
  --input-lg-height: 40px;
  --input-lg-radius: var(--radius-5);
  --input-lg-font-size: 16px;

  --input-description-font-size: 13px;
}

/* Skeleton uses Tailwind's pulse animation; this hook keeps it calm when
   the person prefers reduced motion. */
@media (prefers-reduced-motion: reduce) {
  .espresso-skeleton {
    animation-duration: 2s;
  }
}

/* The handle is positioned by Ark UI; only the drag affordance is ours. */
[data-slot="thumb"] {
  touch-action: none;
  user-select: none;
  -webkit-tap-highlight-color: transparent;
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="thumb"] {
    transition: none;
  }
}

/* Spinner paints a rotating conic-gradient comet inside a masked ring.
   The gradient angle is registered so it can interpolate smoothly. */
@property --spinner-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

.espresso-spinner {
  --spinner-thickness: 14.7%;
  --spinner-mask-thickness: 29.4%;
  --spinner-inset: 7.5%;
  --spinner-paint-size: calc(100% - 2 * var(--spinner-inset));
  --spinner-track-color: transparent;
  background-image:
    radial-gradient(
      calc(var(--spinner-thickness) / 2) calc(var(--spinner-thickness) / 2) at
        calc(50% + (50% - var(--spinner-thickness) / 2) * sin(var(--spinner-angle)))
        calc(50% - (50% - var(--spinner-thickness) / 2) * cos(var(--spinner-angle))),
      currentColor 92%,
      transparent
    ),
    conic-gradient(from var(--spinner-angle), transparent 32%, currentColor 92%, currentColor 100%),
    linear-gradient(var(--spinner-track-color), var(--spinner-track-color));
  background-size: var(--spinner-paint-size) var(--spinner-paint-size);
  background-position: center;
  background-repeat: no-repeat;
  -webkit-mask: radial-gradient(
      farthest-side,
      transparent calc(100% - var(--spinner-mask-thickness)),
      #000 calc(100% - var(--spinner-mask-thickness)),
      #000 calc(100% - 0.5px),
      transparent 100%
    )
    center / var(--spinner-paint-size) var(--spinner-paint-size) no-repeat;
  mask: radial-gradient(
      farthest-side,
      transparent calc(100% - var(--spinner-mask-thickness)),
      #000 calc(100% - var(--spinner-mask-thickness)),
      #000 calc(100% - 0.5px),
      transparent 100%
    )
    center / var(--spinner-paint-size) var(--spinner-paint-size) no-repeat;
  animation: espresso-spinner-rotate 0.7s linear infinite;
}

.espresso-spinner--track {
  --spinner-track-color: color-mix(in srgb, currentColor 15%, transparent);
}

@keyframes espresso-spinner-rotate {
  to {
    --spinner-angle: 360deg;
  }
}

@media (prefers-reduced-motion: reduce) {
  .espresso-spinner {
    animation-duration: 1.6s;
  }
}

/* Switch component tokens — mirrors frappe-ui v1 toggle geometry. */
:root {
  --switch-radius: var(--radius-full);
  --switch-padded-radius: var(--radius-4);

  --switch-xs-height: 14px;
  --switch-xs-width: 24px;
  --switch-xs-thumb-size: 10px;
  --switch-xs-travel: 10px;

  --switch-sm-height: 16px;
  --switch-sm-width: 26px;
  --switch-sm-thumb-size: 12px;
  --switch-sm-travel: 10px;

  --switch-md-height: 20px;
  --switch-md-width: 32px;
  --switch-md-thumb-size: 14px;
  --switch-md-travel: 12px;

  --input-description-font-size: 13px;
}

/* The active surface slides between options; the track keeps the motion short. */
[data-slot="tab-indicator"] {
  will-change: transform, width, height;
}

[data-slot="tab-button"] {
  -webkit-tap-highlight-color: transparent;
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="tab-indicator"] {
    transition: none;
  }
}

/* Tabs use color transitions only; the moving indicator is intentionally omitted. */
[data-slot="tab-trigger"] {
  -webkit-tap-highlight-color: transparent;
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="tab-trigger"] {
    transition: none;
  }
}

/* TextInput component tokens — mirrors frappe-ui v1 control geometry. */
:root {
  /* Size: xs (24px) */
  --input-xs-height: 24px;
  --input-xs-radius: var(--radius-3);
  --input-xs-font-size: 12px;

  /* Size: sm (28px) */
  --input-sm-height: 28px;
  --input-sm-radius: var(--radius-4);
  --input-sm-font-size: 14px;

  /* Size: md (32px) */
  --input-md-height: 32px;
  --input-md-radius: var(--radius-4);
  --input-md-font-size: 14px;

  /* Size: lg (40px) */
  --input-lg-height: 40px;
  --input-lg-radius: var(--radius-5);
  --input-lg-font-size: 16px;

  --input-description-font-size: 13px;
}

/* Textarea component tokens — mirrors frappe-ui v1 textarea geometry. */
:root {
  --input-xs-radius: var(--radius-3);
  --input-sm-radius: var(--radius-4);
  --input-md-radius: var(--radius-4);
  --input-lg-radius: var(--radius-5);

  --textarea-xs-min-height: 32px;
  --textarea-sm-min-height: 36px;
  --textarea-md-min-height: 40px;
  --textarea-lg-min-height: 44px;
  --textarea-font-size: 13px;

  --input-description-font-size: 13px;
}

/* Tooltip enters from its trigger with a short, origin-aware scale. */
[data-slot="tooltip-content"] {
  transform-origin: var(--transform-origin);
  transition:
    opacity 125ms ease-out,
    transform 125ms ease-out;
}

[data-slot="tooltip-content"][data-state="closed"] {
  opacity: 0;
  transform: scale(0.97);
}

[data-slot="tooltip-arrow"] {
  --arrow-size: 8px;
  --arrow-background: var(--surface-gray-10);
}

[data-slot="tooltip-arrow-tip"] {
  width: var(--arrow-size);
  height: var(--arrow-size);
  border-radius: 2px;
  background: var(--arrow-background);
  transform: rotate(45deg);
}

@media (prefers-reduced-motion: reduce) {
  [data-slot="tooltip-content"] {
    transition: opacity 125ms ease;
  }

  [data-slot="tooltip-content"][data-state="closed"] {
    transform: none;
  }
}
